import { useState } from "react";
import Card from "../../components/common/Card";
import { Link, useParams, useNavigate } from "react-router-dom";
import api from "../../api/api";
import {
  FaArrowLeft,
  FaEye,
  FaFilter,
  FaArrowDownWideShort,
  FaArrowUpWideShort,
  FaChevronLeft,
  FaChevronRight,
} from "react-icons/fa6";
import { CgSpinnerAlt } from "react-icons/cg";
import type { PatientInterface } from "../../interfaces/PatientInterface";
import RiskLevel from "../../components/common/RiskLevel";
import RiskProgressChart from "../../components/doctor/RiskProgressChart";
import { format } from "date-fns/format";
import { es } from "date-fns/locale";
import { parsePhoneNumberWithError } from "libphonenumber-js";
import { useQuery } from "@tanstack/react-query";

const PatientDetails = () => {
  const { patientId } = useParams<{ patientId: string }>();
  const navigate = useNavigate();
  const [assessmentsAll, setAssessmentsAll] = useState<any[]>([]);
  const [riskFilter, setRiskFilter] = useState("Todos");
  const [sortOrder, setSortOrder] = useState<"desc" | "asc">("desc");
  const [currentPage, setCurrentPage] = useState(0);
  // const [totalPages, setTotalPages] = useState(0);

  const { data: patientData, isLoading: isLoadingPatientData } =
    useQuery<PatientInterface>({
      queryKey: ["patientData", patientId],
      queryFn: async () => {
        const response = await api.get(`/patients/${patientId}`);
        return response.data;
      },
    });

  const labelParam = riskFilter === "Todos" ? "all" : riskFilter;

  const { data: assessmentsData, isLoading: isLoadingAssessments } = useQuery({
    queryKey: [
      "assessmentsData",
      patientId,
      riskFilter,
      sortOrder,
      currentPage,
    ],
    queryFn: async () => {
      const res = await api.get(`/patients/${patientId}/assessments`, {
        params: {
          riskLabel: labelParam,
          sort: `createdAt,${sortOrder}`,
          size: 100,
          page: currentPage,
        },
      });
      return res.data;
    },
  });
  if (labelParam === "all") setAssessmentsAll(assessmentsData?.content || []);
  const assessments = assessmentsData?.content || [];
  const totalPages = assessmentsData?.totalPages || 0;

  const formatPhone = (phone: any) => {
    try {
      const phoneNumber = parsePhoneNumberWithError(
        phone.startsWith("+") ? phone : `+${phone}`,
      );
      return phoneNumber.formatInternational();
    } catch (error) {
      return phone;
    }
  };

  const handleFilterChange = (val: string) => {
    setRiskFilter(val);
    setCurrentPage(0);
  };

  const handleSortToggle = () => {
    setSortOrder(sortOrder === "desc" ? "asc" : "desc");
    setCurrentPage(0);
  };

  if (isLoadingPatientData && isLoadingAssessments) {
    return (
      <div className="w-full h-full flex justify-center items-center">
        <CgSpinnerAlt size={40} className="animate-spin text-indigo-500" />
      </div>
    );
  }

  const selectClass =
    "bg-white dark:bg-slate-900 border border-gray-200 dark:border-slate-700 text-gray-700 dark:text-gray-300 text-xs rounded-lg focus:ring-indigo-500 focus:border-indigo-500 block p-2 px-3 cursor-pointer outline-none";

  const paginationBtnClass =
    "p-2 cursor-pointer rounded-md border border-gray-200 dark:border-slate-700 text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-slate-800 disabled:opacity-30 disabled:cursor-not-allowed transition-colors";

  return (
    <div className="flex flex-1 relative -top-1 2xl:-top-5 flex-col h-full">
      <div className="flex flex-col sticky md:static -top-1 md:pb-2 items-center bg-white dark:bg-slate-800 z-10 justify-start h-fit">
        <div className="w-full ml-2">
          <Link
            to="/patients"
            className="flex items-center w-fit text-gray-500 hover:text-indigo-500 dark:text-slate-300 dark:hover:text-indigo-400 transition-colors"
          >
            <FaArrowLeft className="mr-2" />
            <span>Regresar</span>
          </Link>
        </div>
        <div className="md:hidden w-full h-7 bg-white dark:bg-slate-900 z-10 rounded-t-lg"></div>
      </div>

      <div className="space-y-4 w-full flex flex-1 flex-col">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 xl:h-90">
          <Card styles="col-span-1 p-6 pt-0 flex flex-col items-center text-center md:!rounded-lg !rounded-t-none">
            <div className="w-19 h-19 bg-indigo-100 dark:bg-slate-800 rounded-full flex items-center justify-center text-2xl font-bold text-indigo-600 mb-4">
              {patientData?.name.charAt(0)}
            </div>
            <h1 className="text-xl font-bold text-gray-900 dark:text-white">
              {patientData?.name + " " + (patientData?.lastname || "")}
            </h1>
            <p className="text-gray-500 dark:text-gray-400">
              {patientData?.email || "Sin correo registrado"}
            </p>
            <div className="w-full border-t border-gray-100 dark:border-slate-700 pt-4 mt-2 space-y-3">
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Número telefónico:</span>
                <span className="font-medium dark:text-gray-200">
                  {formatPhone(patientData?.number)}
                </span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Edad:</span>
                <span className="font-medium dark:text-gray-200">
                  {patientData?.age + " años"}
                </span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Fecha de nacimiento:</span>
                <span className="font-medium dark:text-gray-200">
                  {format(
                    new Date(patientData?.dateOfBirth ?? " "),
                    "dd/MMM/yyyy",
                    {
                      locale: es,
                    },
                  )}
                </span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Género:</span>
                <span className="font-medium dark:text-gray-200">
                  {patientData?.gender === "MALE" ? "Masculino" : "Femenino"}
                </span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Etnia:</span>
                <span className="font-medium dark:text-gray-200">
                  {patientData?.ethnicity}
                </span>
              </div>
            </div>
          </Card>

          <Card styles="col-span-1 lg:col-span-2 p-6 h-90">
            <h2 className="text-lg font-semibold mb-4 dark:text-white text-gray-800">
              Progreso del Riesgo Metabólico
            </h2>
            <RiskProgressChart data={assessmentsAll || []} />
          </Card>
        </div>

        <Card styles="p-0 overflow-hidden h-full flex flex-col">
          <div className="px-6 py-4 flex flex-col sm:flex-row justify-between items-center gap-4">
            <h2 className="text-xl font-semibold dark:text-white text-gray-800">
              Historial Clínico
            </h2>

            <div className="flex items-center gap-3">
              <div className="flex items-center gap-2">
                <FaFilter className="text-gray-400 text-sm" />
                <select
                  value={riskFilter}
                  onChange={(e) => handleFilterChange(e.target.value)}
                  className={selectClass}
                >
                  <option value="Todos">Todos los niveles</option>
                  <option value="high">Alto</option>
                  <option value="medium">Medio</option>
                  <option value="low">Bajo</option>
                </select>
              </div>

              <button
                onClick={handleSortToggle}
                className={`${selectClass} flex items-center gap-2 hover:bg-gray-50 dark:hover:bg-slate-800 transition-colors`}
              >
                {sortOrder === "desc" ? (
                  <FaArrowDownWideShort />
                ) : (
                  <FaArrowUpWideShort />
                )}
                <span className="hidden sm:inline">
                  {sortOrder === "desc" ? "Más recientes" : "Más antiguos"}
                </span>
              </button>
            </div>
          </div>

          <div className="overflow-y-auto overflow-x-hidden max-h-150 min-h-80 h-full dark:bg-slate-800 rounded-t-xl backdrop-blur-sm border-x border-t border-gray-300 dark:border-slate-700 relative">
            {isLoadingAssessments && (
              <div className="absolute inset-0 bg-white/40 dark:bg-slate-900/40 z-10 flex justify-center items-center">
                <CgSpinnerAlt
                  size={30}
                  className="animate-spin text-indigo-500"
                />
              </div>
            )}

            <table className="w-full text-left">
              <thead className="sticky top-0 z-9 bg-indigo-600 text-white uppercase font-medium">
                <tr className="text-sm">
                  <th className="px-6 py-3 text-xs md:text-sm">Fecha</th>
                  <th className="px-6 py-3 text-xs md:text-sm">Hora</th>
                  <th className="px-6 text-center py-3 text-xs md:text-sm">
                    Riesgo
                  </th>
                  <th className="px-1 md:px-6 py-3 text-center text-xs md:text-sm ">
                    Acciones
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-300 dark:divide-slate-700">
                {assessments.length > 0 ? (
                  assessments.map((ev: any) => (
                    <tr
                      key={ev.id}
                      className="dark:bg-slate-800 dark:text-white hover:dark:bg-slate-700 hover:bg-gray-100 transition-all"
                    >
                      <td className="hidden md:block px-4 py-2 md:px-6 md:py-4 text-xs md:text-sm">
                        {format(new Date(ev.createdAt), "dd 'de' MMMM, yyyy", {
                          locale: es,
                        })}
                      </td>
                      <td className="md:hidden px-2 py-2 md:px-6 md:py-4 text-xs md:text-sm">
                        {format(new Date(ev.createdAt), "dd/MM/yyyy", {
                          locale: es,
                        })}
                      </td>
                      <td className="px-4 py-2 md:px-6 md:py-4 text-xs md:text-sm">
                        {format(new Date(ev.createdAt), "hh:mm a")}
                      </td>
                      <td className="text-center px-4 py-2 md:px-6 md:py-4 text-xs md:text-sm">
                        <RiskLevel level={ev.riskLabel} />
                      </td>
                      <td className="px-4 py-5 md:px-6 md:py-4 text-xs flex-1 items-center flex justify-center md:text-sm">
                        <button
                          onClick={() => navigate(`assessment/${ev.id}`)}
                          className="cursor-pointer text-indigo-600 dark:text-indigo-200 dark:hover:text-indigo-400 hover:text-indigo-800 font-medium text-sm flex items-center gap-1 text-center group"
                        >
                          <FaEye className="group-hover:scale-115 transition-transform" />
                          <span className="hidden md:block">Ver Detalle</span>
                          <span className="md:hidden ">Ver</span>
                        </button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td
                      colSpan={4}
                      className="px-6 py-10 text-center text-gray-500 italic text-sm"
                    >
                      No se encontraron evaluaciones con los filtros
                      seleccionados.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          <div className="px-6 py-3 bg-gray-50 dark:bg-slate-900 border-t border-gray-300 dark:border-slate-700 flex items-center justify-between">
            <span className="text-xs text-gray-500 dark:text-gray-400 font-medium">
              Página {totalPages === 0 ? 0 : currentPage + 1} de {totalPages}
            </span>

            <div className="flex gap-2">
              <button
                onClick={() => setCurrentPage((prev) => Math.max(0, prev - 1))}
                disabled={currentPage === 0 || isLoadingAssessments}
                className={paginationBtnClass}
              >
                <FaChevronLeft size={14} />
              </button>

              <button
                onClick={() => setCurrentPage((prev) => prev + 1)}
                disabled={currentPage >= totalPages - 1 || isLoadingAssessments}
                className={paginationBtnClass}
              >
                <FaChevronRight size={14} />
              </button>
            </div>
          </div>
        </Card>
      </div>
    </div>
  );
};

